local procedure EvaluateResponse(HttpResponseMessage: HttpResponseMessage) Retry: Boolean
    var
        Status: Integer;
    begin
        Status := HttpResponseMessage.HttpStatusCode();
        case Status of
            429:
                begin
                    Sleep(2000);
                    Retry := true;
                end;
            500 .. 599:
                begin
                    Sleep(10000);
                    Retry := true;
                end;
        end;
    end;
